def Creer_type_conges(apps, schema_editor):
    """ Crée le type « Congés annuels » s'il existe une catégorie d'évènements de congés """
    TypeCongeCollaborateur = apps.get_model("core", "TypeCongeCollaborateur")
    TypeEvenementCollaborateur = apps.get_model("core", "TypeEvenementCollaborateur")
    if TypeCongeCollaborateur.objects.exists():
        return
    categorie = TypeEvenementCollaborateur.objects.filter(nom__icontains="cong").exclude(type="ADDITION").order_by("pk").first()
    if categorie:
        TypeCongeCollaborateur.objects.create(nom="Congés annuels", abrege="CA", unite="JOURS", categorie=categorie, mois_debut=1)


def Supprimer_type_conges(apps, schema_editor):
    pass


